649	    /**
650	     * Normalize a household field (such as last name or address) to its canonical form for
651	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
652	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
653	     * that differ only in letter case or spacing are treated as the same value.
654	     *
655	     * @param value the raw field value, possibly {@code null}
656	     * @return the normalized form, or {@code null} if the input was {@code null}
657	     */
658	    public static String normalizeHousehold(String value) {
659	        if (value == null) {
660	            return null;
661	        }
662	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
663	    }
