723	    /**
724	     * Build an owner's {@code memberId}, the single unified owner identity assigned once when the owner
725	     * is created. It is formatted {@code '<REGION><FY><HASH8><CHK>'} (no separators) where:
726	     * <ul>
727	     *   <li>{@code REGION} is the version-2 region code derived from the postcode (see
728	     *       {@link #identityRegion(String)}): the plain region code with the fixed
729	     *       {@link #IDENTITY_VERSION 'V2'} tag mixed in, or {@code 'UNKNOWNV2'} when the postcode is
730	     *       absent or in no known range,</li>
731	     *   <li>{@code FY} is the two-digit fiscal year of the registration date (the last two digits of
732	     *       the fiscal-year number, see {@link #fiscalYearNumber(LocalDate)}),</li>
733	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
734	     *       {@link #IDENTITY_VERSION 'V2'} tag, the normalized telephone (see
735	     *       {@link #normalizeTelephone(String)}) and the last name, and</li>
736	     *   <li>{@code CHK} is a single Luhn check digit (see {@link #luhn(String)}) over the digits of the
737	     *       {@code <REGION><FY><HASH8>} prefix.</li>
738	     * </ul>
739	     * The value is deterministic in the postcode, telephone, last name and registration date (e.g.
740	     * {@code 'NSWV2271A2B3C4D5'}); it carries no sequence number. The {@code 'V2'} tag mixed into both
741	     * the region code and the hash makes the version-2 member id differ from the version-1 value for
742	     * the same owner.
743	     *
744	     * @param postcode the owner's postcode, possibly {@code null}
745	     * @param telephone the owner's raw telephone, possibly {@code null}
746	     * @param lastName the owner's last name, possibly {@code null}
747	     * @param registrationDate the owner's registration date, possibly {@code null}
748	     * @return the member id, or {@code null} if the telephone, last name or registration date is
749	     *     {@code null}
750	     */
751	    public static String memberId(String postcode, String telephone, String lastName,
752	            LocalDate registrationDate) {
753	        if (telephone == null || lastName == null || registrationDate == null) {
754	            return null;
755	        }
756	        String region = identityRegion(postcode);
757	        String fy = String.format("%02d", fiscalYearNumber(registrationDate) % 100);
758	        String normalizedTelephone = normalizeTelephone(telephone);
759	        String key = IDENTITY_VERSION + (normalizedTelephone == null ? "" : normalizedTelephone)
760	            + lastName;
761	        String hash8 = sha256Hex(key).substring(0, 8).toUpperCase();
762	        String prefix = region + fy + hash8;
763	        return prefix + luhn(prefix);
764	    }
