785	    /**
786	     * Compute an owner's {@code identityKey}, the single derived value through which all
787	     * duplicate detection is now expressed. It is the lower-case hex SHA-256 digest (see
788	     * {@link #sha256Hex(String)}) of the fixed {@link #IDENTITY_VERSION 'V2'} version tag and the three
789	     * identity components joined with {@code '|'}:
790	     * {@code IDENTITY_VERSION + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
791	     * where
792	     * <ul>
793	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
794	     *   <li>the lower-cased email (see {@link #normalizeEmail(String)}), or the empty string
795	     *       when no email is present, and</li>
796	     *   <li>the Soundex code of the last name (see {@link #soundex(String)}).</li>
797	     * </ul>
798	     * A {@code null} component is rendered as the empty string before hashing. The {@code 'V2'} tag
799	     * mixed into the digest makes the version-2 identity key differ from the version-1 value for the
800	     * same owner. Two owners are the same identity only when their <em>whole</em> keys are equal;
801	     * because the telephone is part of the key, two members of the same household (same last name and
802	     * postcode) with different telephones have different keys and are not a hard duplicate.
803	     *
804	     * @param telephone the owner's raw telephone, possibly {@code null}
805	     * @param email the owner's email, possibly {@code null}
806	     * @param lastName the owner's last name, possibly {@code null}
807	     * @return the 64-character lower-case hex identity key, never {@code null}
808	     */
809	    public static String identityKey(String telephone, String email, String lastName) {
810	        String normalizedTelephone = normalizeTelephone(telephone);
811	        String normalizedEmail = normalizeEmail(email);
812	        String lastNameSoundex = soundex(lastName);
813	        String raw = IDENTITY_VERSION
814	            + "|" + (normalizedTelephone == null ? "" : normalizedTelephone)
815	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
816	            + "|" + (lastNameSoundex == null ? "" : lastNameSoundex);
817	        return sha256Hex(raw);
818	    }
