880	    /**
881	     * The month in which the fiscal year starts (1 July). Dates on or after this month belong to
882	     * the fiscal year named for the following calendar year.
883	     */
884	    private static final int FISCAL_YEAR_START_MONTH = 7;
885	
886	    /**
887	     * Resolve the fiscal-year number for a date, where the fiscal year starts on 1 July and is
888	     * named for the calendar year in which it ends. A date in July&ndash;December belongs to the
889	     * fiscal year of the next calendar year; a date in January&ndash;June belongs to the fiscal
890	     * year of its own calendar year.
891	     *
892	     * @param date the date to resolve, never {@code null}
893	     * @return the fiscal-year number (a four-digit calendar year)
894	     */
895	    private static int fiscalYearNumber(LocalDate date) {
896	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
897	    }
