915	    /**
916	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
917	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
918	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
919	     * and gains 3 when the owner's tenure is more than one fiscal year (the tenure being the number
920	     * of elapsed fiscal years from {@code registrationDate} to today, see
921	     * {@link #fiscalYear(LocalDate)}). Because a newly created owner has zero tenure, the tenure
922	     * points accrue only once the owner has been a member for more than a full fiscal year.
923	     *
924	     * @param namesakeCount the owner's namesake count, possibly {@code null}
925	     * @param email the owner's email, possibly {@code null}
926	     * @param householdCount the number of members in the owner's household, possibly {@code null}
927	     * @param registrationDate the owner's registration date, possibly {@code null}
928	     * @return the membership points, a non-negative integer
929	     */
930	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
931	            LocalDate registrationDate) {
932	        int points = 0;
933	        if (email != null && !email.isEmpty()) {
934	            points += 2;
935	        }
936	        if (namesakeCount != null && namesakeCount == 0) {
937	            points += 1;
938	        }
939	        if (householdCount != null && householdCount >= 3) {
940	            points += 2;
941	        }
942	        if (registrationDate != null
943	            && fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1) {
944	            points += 3;
945	        }
946	        return points;
947	    }
948	
949	    /**
950	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
951	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
952	     *
953	     * @param membershipPoints the owner's membership points
954	     * @return the membership level, an integer from 1 to 4
955	     */
956	    public static int membershipLevel(int membershipPoints) {
957	        if (membershipPoints >= 6) {
958	            return 4;
959	        }
960	        if (membershipPoints >= 4) {
961	            return 3;
962	        }
963	        if (membershipPoints >= 2) {
964	            return 2;
965	        }
966	        return 1;
967	    }
968	
969	    /**
970	     * Resolve this owner's effective {@code membershipLevel}: the capped value stored on the owner
971	     * when present (the create-time level after the household ceiling has been applied, see
972	     * {@link #getMembershipLevel()}), otherwise the level recomputed from the owner's membership
973	     * points (see {@link #membershipLevel(int)} and
974	     * {@link #membershipPoints(Integer, String, Integer, LocalDate)}). This is the single source of
975	     * truth for how a stored level is read back, deferred to by both the create-time household-ceiling
976	     * computation and the read-side DTO mapping so they always agree.
977	     *
978	     * @return the stored capped level when present, otherwise the level derived from membership points
979	     */
980	    public int effectiveMembershipLevel() {
981	        if (this.membershipLevel != null) {
982	            return this.membershipLevel;
983	        }
984	        return membershipLevel(membershipPoints(this.namesakeCount, this.email,
985	            this.householdCount, this.registrationDate));
986	    }
