988	    /**
989	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
990	     * for postcode validation, keyed by the exact city name.
991	     */
992	    private static final Map<String, String> CITY_REGION = Map.of(
993	        "Sydney", "NSW",
994	        "Melbourne", "VIC",
995	        "Brisbane", "QLD");
