997	    /**
998	     * Derive an owner's {@code locality}, the canonical region for the owner, directly from the
999	     * owner's postcode (see {@link #regionForPostcode(String)}). This is the <em>plain</em> region
1000	     * code ({@code 'NSW'}, {@code 'VIC'} or {@code 'QLD'}), or {@code 'UNKNOWN'} when the postcode is
1001	     * absent or in no known range. The locality is user-facing and is <em>not</em> an identifier, so
1002	     * it never carries the {@link #IDENTITY_VERSION 'V2'} version tag that the identifiers mix into
1003	     * their own region code (see {@link #identityRegion(String)}).
1004	     *
1005	     * @param postcode the owner's postcode, possibly {@code null}
1006	     * @return the plain region string, or {@code 'UNKNOWN'} when no region can be derived
1007	     */
1008	    public static String locality(String postcode) {
1009	        String region = regionForPostcode(postcode);
1010	        return region == null ? "UNKNOWN" : region;
1011	    }
1012	
1013	    /**
1014	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
1015	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
1016	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
1017	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
1018	     */
1019	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
1020	        "NSW", "Australia/Sydney",
1021	        "VIC", "Australia/Melbourne",
1022	        "QLD", "Australia/Brisbane");
1023	
1024	    /**
1025	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
1026	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
1027	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
1028	     * is the owner's {@code locality} (see {@link #locality(String)}), the plain region code derived
1029	     * from the postcode. A region not in the table (including {@code 'UNKNOWN'}) has no timezone and
1030	     * yields {@code null}.
1031	     *
1032	     * @param postcode the owner's postcode, possibly {@code null}
1033	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
1034	     */
1035	    public static String timezone(String postcode) {
1036	        return REGION_TIMEZONE.get(locality(postcode));
1037	    }
